import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry validation constraints [specs/hal-engine-tool-input-validation/spec.md#7]', () => {
  it('logs the expected type on rejection', async () => {
    const warn = jest.fn();
    setLogger({debug: jest.fn(), info: jest.fn(), warn, error: jest.fn()});
    try {
      const registry = new ToolRegistry();
      registry.register({name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}}, async () => 'ok');
      await registry.execute('weather', {location: 123456789});
      expect(JSON.stringify(warn.mock.calls)).toEqual(expect.stringContaining('type: string'));
    } finally {
      setLogger();
    }
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.constraint.test.ts"
